<template>
  <ion-page>
    <ion-header><ion-toolbar><ion-buttons slot="start"><AppBackButton default-href="/tabs/esti-deploy" /></ion-buttons><ion-title>{{ t('budget.detail.title') }}</ion-title></ion-toolbar></ion-header>
    <ion-content class="budget-detail-content">
      <section v-if="loading" class="state-page"><ion-spinner name="crescent" color="primary" /><span>{{ t('budget.detail.loading') }}</span></section>
      <section v-else-if="error" class="state-page"><AlertCircle :size="34" color="#b42318" /><strong>{{ t('budget.detail.loadFailed') }}</strong><p>{{ error }}</p><ion-button @click="load">{{ t('common.reload') }}</ion-button></section>
      <main v-else class="budget-detail" :aria-label="t('budget.detail.title')">
        <header class="title-band"><h1>{{ store.name || t('budget.detail.unnamedTitle') }}</h1><span v-if="store.shipName || store.shipId">{{ store.shipName || store.shipId }}</span><p v-if="store.deployDesc">{{ store.deployDesc }}</p><small>{{ t('budget.detail.lastUpdated', { value: dateText(store.lastUpdatedAt) }) }}</small></header>

        <section class="detail-section" aria-labelledby="cargo-heading">
          <h2 id="cargo-heading">{{ t('budget.detail.cargo') }}</h2>
          <p v-if="!document.cargos.length" class="empty-note">{{ t('budget.detail.noCargo') }}</p>
          <article v-for="(cargo, index) in document.cargos" :key="cargo.id" class="cargo-row">
            <strong>{{ index + 1 }}. {{ cargo.name || t('budget.detail.unnamedCargo') }}</strong>
            <div class="cargo-route"><span>{{ portName(cargo.loadPortId) }}</span><ArrowRight :size="15" /><span>{{ portName(cargo.dischargePortId) }}</span></div>
            <div class="three-column-grid cargo-grid"><div><span>{{ t('budget.detail.quantity') }}</span><span class="plain-value">{{ amount(cargo.quantity) }}</span></div><div><span>{{ t('budget.detail.freight') }}</span><span class="plain-value">{{ amount(cargo.freight) }}</span></div><div><span>{{ t('budget.detail.income') }}</span><span class="plain-value">{{ amount(cargo.income) }}</span></div></div>
            <div class="three-column-grid charge-grid cargo-grid"><div><span>{{ t('budget.detail.addComm') }}</span><span class="plain-value">{{ amount(cargo.addCommRate) }}{{ t('common.unit.percent') }} {{ amount(cargoCommission(cargo, 'addCommRate')) }}</span></div><div><span>{{ t('budget.detail.brokerage') }}</span><span class="plain-value">{{ amount(cargo.brokerageRate) }}{{ t('common.unit.percent') }} {{ amount(cargoCommission(cargo, 'brokerageRate')) }}</span></div><div><span>{{ t('budget.detail.freightTax') }}</span><span class="plain-value">{{ amount(cargo.frtTaxRate) }}{{ t('common.unit.percent') }} {{ amount(cargoCommission(cargo, 'frtTaxRate')) }}</span></div></div>
            <div class="two-column-grid cargo-grid"><div><span>{{ t('budget.detail.demurrage') }}</span><span class="plain-value">{{ amount(cargo.demurrage) }}</span></div><div><span>{{ t('budget.detail.dispatch') }}</span><span class="plain-value">{{ amount(cargo.dispatch) }}</span></div></div>
          </article>
          <div v-if="document.cargos.length > 1" class="cargo-subtotal"><strong>{{ t('budget.detail.cargoSubtotal') }}</strong><div class="three-column-grid cargo-grid"><div><span>{{ t('budget.detail.income') }}</span><span class="plain-value">{{ amount(cargoTotals.income) }}</span></div><div><span>{{ t('budget.detail.addCommTotal') }}</span><span class="plain-value">{{ amount(cargoTotals.addComm) }}</span></div><div><span>{{ t('budget.detail.brokerageTotal') }}</span><span class="plain-value">{{ amount(cargoTotals.brokerage) }}</span></div><div><span>{{ t('budget.detail.freightTaxTotal') }}</span><span class="plain-value">{{ amount(cargoTotals.tax) }}</span></div><div><span>{{ t('budget.detail.demurrage') }}</span><span class="plain-value">{{ amount(cargoTotals.demurrage) }}</span></div><div><span>{{ t('budget.detail.dispatch') }}</span><span class="plain-value">{{ amount(cargoTotals.dispatch) }}</span></div></div></div>
        </section>

        <section class="detail-section" aria-labelledby="fuel-speed-heading">
          <h2 id="fuel-speed-heading">{{ t('budget.detail.fuelSpeedTitle') }}</h2>
          <p class="section-note">{{ t('budget.detail.fuelSpeedNote') }}</p>
          <div class="three-column-grid metric-grid fuel-metric-grid"><div><span>{{ t('budget.detail.ladenMainEngine') }}</span><strong>{{ amount(document.fuel.seaLadenFuel) }}</strong></div><div><span>{{ t('budget.detail.ballastMainEngine') }}</span><strong>{{ amount(document.fuel.seaBallastFuel) }}</strong></div><div><span>{{ t('budget.detail.seaAuxiliary') }}</span><strong>{{ amount(document.fuel.seaAuxFuel) }}</strong></div><div><span>{{ t('budget.detail.idleInPort') }}</span><strong>{{ amount(document.fuel.portIdleFuel) }}</strong></div><div><span>{{ t('budget.detail.workingInPort') }}</span><strong>{{ amount(document.fuel.portWorkingFuel) }}</strong></div></div>
          <div class="four-column-grid speed-grid"><div><span>{{ t('budget.detail.ballastFullSpeed') }}</span><strong>{{ amount(document.speeds.ballastFullSpeed) }}</strong></div><div><span>{{ t('budget.detail.ballastEcoSpeed') }}</span><strong>{{ amount(document.speeds.ballastEcoSpeed) }}</strong></div><div><span>{{ t('budget.detail.ladenFullSpeed') }}</span><strong>{{ amount(document.speeds.ladenFullSpeed) }}</strong></div><div><span>{{ t('budget.detail.ladenEcoSpeed') }}</span><strong>{{ amount(document.speeds.ladenEcoSpeed) }}</strong></div></div>
        </section>

        <section class="detail-section" aria-labelledby="port-heading">
          <div class="section-heading"><h2 id="port-heading">{{ t('budget.detail.portRotation') }}</h2><ion-button v-if="document.mapRoute?.rawRoutePoints.length" fill="clear" size="small" @click="router.push({ name: 'esti-deploy-map', query: { readonly: '1' } })"><Map :size="16" /> {{ t('budget.detail.viewMap') }}</ion-button></div>
          <div class="route-total-panel"><div class="route-total-grid"><div><span>{{ t('budget.detail.totalDistance') }}</span><strong>{{ amount(results.totalDistanceNm) }}</strong></div><div><span>{{ t('budget.detail.ecaDistance') }}</span><strong>{{ amount(results.totalEcaDistanceNm) }}</strong></div><div><span>{{ t('budget.detail.sailingDays') }}</span><strong>{{ amount(results.totalSeaDays) }}</strong></div><div><span>{{ t('budget.detail.daysInPort') }}</span><strong>{{ amount(results.totalIdleDays + results.totalWorkDays) }}</strong></div><div><span>{{ t('budget.detail.voyageDays') }}</span><strong>{{ amount(results.totalVoyageDays) }}</strong></div></div><div v-if="document.routeCalculated" class="route-fuel-summary"><strong>{{ t('budget.detail.fuelSummary') }}</strong><div class="three-column-grid stacked-grid fuel-summary-grid"><div><span>{{ mainFuelType }}</span><strong>{{ amount(results.seaMainFuel) }} {{ t('common.unit.tonneShort') }}</strong></div><div><span>{{ t('budget.detail.mgoEcaLabel') }}</span><strong>{{ amount(results.ecaMainFuel) }} {{ t('common.unit.tonneShort') }}</strong></div><div><span>{{ t('budget.detail.mgoAuxiliaryLabel') }}</span><strong>{{ amount(results.seaAuxFuel) }} {{ t('common.unit.tonneShort') }}</strong></div><div><span>{{ t('budget.detail.mgoPortLabel') }}</span><strong>{{ amount(results.portFuel) }} {{ t('common.unit.tonneShort') }}</strong></div><div><span>{{ t('budget.detail.totalFuel') }}</span><strong>{{ amount(results.totalFuel) }} {{ t('common.unit.tonneShort') }}</strong></div></div></div></div>
          <div v-if="hasPortMargins" class="margin-summary"><strong>{{ t('budget.detail.overallPortMargin') }}</strong><span v-if="results.totalIdleDays > 0">{{ t('budget.detail.waitingForBerth', { value: amount(document.margins.portIdleDays) }) }}</span><span v-if="results.totalWorkDays > 0">{{ t('budget.detail.working', { value: amount(document.margins.portWorkingDays) }) }}</span><span>{{ t('budget.detail.extraMgo', { value: amount(portMarginFuel) }) }}</span></div>
          <p v-if="!document.ports.length" class="empty-note">{{ t('budget.detail.noPorts') }}</p>
          <article v-for="(port, index) in document.ports" :key="port.id" class="port-row">
            <div class="port-head"><div><strong :class="{ 'route-point-name': isRoutingPort(port) }">{{ index + 1 }}. {{ portDisplayName(port) }}</strong><span v-if="!isRoutingPort(port)">{{ taskLabel(port.taskType) }}<template v-if="index < document.ports.length - 1"> · {{ port.isLaden ? t('budget.detail.laden') : t('budget.detail.ballast') }} · {{ port.speedMode === 'eco' ? t('budget.detail.eco') : t('budget.detail.full') }}</template></span><span v-else>{{ t('budget.detail.waypoint') }}</span></div></div>
            <div v-if="index > 0" class="route-leg-grid"><div><span>{{ t('budget.detail.distance') }}</span><strong>{{ amount(port.distanceNm) }}</strong></div><div><span>{{ t('budget.detail.sailingLabel') }}</span><strong>{{ amount(port.seaDays) }}</strong></div><template v-if="!isRoutingPort(port)"><div><span>{{ t('budget.detail.ecaDistanceLabel') }}</span><strong>{{ amount(port.ecaDistanceNm) }}</strong></div><div><span>{{ t('budget.detail.ecaSailingLabel') }}</span><strong>{{ amount(port.ecaSeaDays) }}</strong></div></template></div>
            <div v-if="!isRoutingPort(port) && port.weatherMarginDays > 0" class="route-margin"><span>{{ t('budget.detail.weatherMargin') }}</span><strong>{{ amount(port.weatherMarginDays) }} {{ t('common.unit.day') }}</strong></div>
            <div v-if="!isRoutingPort(port) && document.routeCalculated" class="port-fuel-panel"><div v-if="index === 0" class="two-column-grid stacked-grid"><div><span>{{ t('budget.detail.mgoIdleLabel') }}</span><strong>{{ amount(port.idleDays * document.fuel.portIdleFuel) }} {{ t('common.unit.tonneShort') }}</strong></div><div><span>{{ t('budget.detail.mgoWorkingLabel') }}</span><strong>{{ amount(port.workDays * document.fuel.portWorkingFuel) }} {{ t('common.unit.tonneShort') }}</strong></div></div><div v-else class="two-column-grid stacked-grid"><div><span>{{ mainFuelForLeg(index) }}</span><strong>{{ amount(fuelLeg(port.id)?.nonEcaMainFuel) }} {{ t('common.unit.tonneShort') }}</strong></div><div><span>{{ t('budget.detail.mgoEcaLabel') }}</span><strong>{{ amount(fuelLeg(port.id)?.ecaMainFuel) }} {{ t('common.unit.tonneShort') }}</strong></div><div><span>{{ t('budget.detail.mgoAuxiliaryLabel') }}</span><strong>{{ amount(fuelLeg(port.id)?.auxiliaryFuel) }} {{ t('common.unit.tonneShort') }}</strong></div><div><span>{{ t('budget.detail.mgoPortLabel') }}</span><strong>{{ amount(fuelLeg(port.id)?.portFuel) }} {{ t('common.unit.tonneShort') }}</strong></div></div></div>
            <div v-if="!isRoutingPort(port)" class="three-column-grid port-operation-grid"><span>{{ t('budget.detail.idle', { value: amount(port.idleDays) }) }}</span><span>{{ t('budget.detail.working', { value: amount(port.workDays) }) }}</span><span>{{ t('budget.detail.portCharges', { value: amount(port.portCharge) }) }}</span></div>
            <div v-if="!isRoutingPort(port)" class="port-times"><div><span>{{ t('budget.detail.etaLabel') }}</span><span class="plain-value">{{ dateText(port.eta) }}</span></div><div><span>{{ t('budget.detail.etdLabel') }}</span><span class="plain-value">{{ dateText(port.etd) }}</span></div></div>
          </article>
        </section>

        <section class="detail-section" aria-labelledby="price-heading">
          <h2 id="price-heading">{{ t('budget.detail.priceTitle') }}</h2>
          <h3>{{ t('budget.detail.unitPrice') }}</h3>
          <div class="two-column-grid metric-grid"><div><span>{{ mainFuelType }}</span><strong>{{ amount(mainFuelPrice) }} /t</strong></div><div><span>LSDO/MGO</span><strong>{{ amount(document.prices.mgoPrice) }} /t</strong></div></div>
          <div v-if="document.routeCalculated" class="fuel-cost-panel"><h3>{{ t('budget.detail.fuelCost') }}</h3><div class="two-column-grid"><div><strong>{{ t('budget.detail.mainFuelCost', { type: mainFuelType }) }}</strong><b>{{ amount(results.nonEcaFuelCost) }}</b><small>{{ t('budget.detail.mainFuelCostFormula', { type: mainFuelType, fuel: amount(results.seaMainFuel), price: amount(mainFuelPrice) }) }}</small></div><div><strong>{{ t('budget.detail.mgoFuelCost') }}</strong><b>{{ amount(mgoFuelCost) }}</b><small>{{ t('budget.detail.mgoFuelCostFormula', { price: amount(document.prices.mgoPrice) }) }}</small></div></div><p>{{ t('budget.detail.totalFuelCost', { value: amount(results.totalFuelCost) }) }}</p></div>
        </section>

        <section class="detail-section" aria-labelledby="cost-heading">
          <h2 id="cost-heading">{{ t('budget.detail.costTitle') }}</h2>
          <div class="three-column-grid metric-grid"><div><span>{{ t('budget.detail.fuelCost') }}</span><strong>{{ amount(results.totalFuelCost) }}</strong></div><div><span>{{ t('budget.detail.portChargesTotal') }}</span><strong>{{ amount(results.totalPortCharge) }}</strong></div><div><span>{{ t('budget.detail.holdCleaning') }}</span><strong>{{ amount(document.costs.ilohc) }}</strong></div><div><span>{{ t('budget.detail.cev') }}</span><strong>{{ amount(document.costs.cev) }}</strong></div><div><span>{{ t('budget.detail.inspection') }}</span><strong>{{ amount(document.costs.inspection) }}</strong></div><div><span>{{ t('budget.detail.otherOperating') }}</span><strong>{{ amount(document.costs.opOther) }}</strong></div><div><span>{{ t('budget.detail.hirePerDay') }}</span><strong>{{ amount(document.costs.hirePerDay) }}</strong></div><div><span>{{ t('budget.detail.hire') }}</span><strong>{{ amount(hireAmount) }}</strong></div><div><span>{{ t('budget.detail.hireCommPercent') }}</span><strong>{{ amount(document.costs.hireCommPercent) }}</strong></div><div><span>{{ t('budget.detail.hireCost') }}</span><strong>{{ amount(hireCost) }}</strong></div><div><span>{{ t('budget.detail.fixedCost') }}</span><strong>{{ amount(document.costs.fixedCost) }}</strong></div></div>
        </section>

        <section class="detail-section result-section" aria-labelledby="result-heading">
          <h2 id="result-heading">{{ t('budget.detail.resultTitle') }}</h2>
          <div class="result-grid"><div v-for="item in resultItems" :key="item.label"><span>{{ item.label }}</span><strong :class="profitClass(item.value)">{{ amount(item.value) }}</strong></div></div>
        </section>
      </main>
    </ion-content>
    <ion-footer v-if="!loading && !error" class="detail-action-bar"><ion-toolbar><div><ion-button fill="clear" @click="edit"><Pencil :size="19" /><span>{{ t('common.edit') }}</span></ion-button><ion-button fill="clear" @click="share"><Share2 :size="19" /><span>{{ t('common.share') }}</span></ion-button><ion-button fill="clear" :disabled="exporting" @click="exportPdf"><FileDown :size="19" /><span>{{ exporting ? t('common.file.exporting') : t('common.file.pdf') }}</span></ion-button><ion-button fill="clear" color="danger" @click="confirmDelete"><Trash2 :size="19" /><span>{{ t('common.delete') }}</span></ion-button></div></ion-toolbar></ion-footer>
  </ion-page>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue'
import { AlertCircle, ArrowRight, FileDown, Map, Pencil, Share2, Trash2 } from 'lucide-vue-next'
import { alertController, IonButton, IonButtons, IonContent, IonFooter, IonHeader, IonPage, IonSpinner, IonTitle, IonToolbar, onIonViewWillEnter, toastController } from '@ionic/vue'
import { useRoute, useRouter } from 'vue-router'
import { useI18n } from 'vue-i18n'
import { useEstiDeployStore } from '@/stores/esti-deploy'
import { shareText } from '@/utils/share'
import { exportVoyageBudgetPdf } from '@/utils/budget-report'
import { formatAmount, formatDateTime } from '@/i18n/format'
import AppBackButton from '@/components/AppBackButton.vue'
import type { BudgetCargo, BudgetPort, BudgetPortTask } from '@/types'

const route = useRoute()
const router = useRouter()
const { t } = useI18n()
const store = useEstiDeployStore()
const loading = ref(true)
const error = ref('')
const exporting = ref(false)
const document = computed(() => store.document)
const results = computed(() => document.value.results)
const mainFuelType = computed(() => document.value.fuel.ladenFuelType === 'HSFO' || document.value.fuel.ballastFuelType === 'HSFO' ? 'HSFO' : 'LSFO')
const mainFuelPrice = computed(() => mainFuelType.value === 'HSFO' ? document.value.prices.hsfoPrice : document.value.prices.lsfoPrice)
const mgoFuelCost = computed(() => results.value.ecaFuelCost + results.value.seaAuxFuelCost + results.value.portFuelCost)
const hireAmount = computed(() => document.value.costs.hirePerDay * results.value.totalVoyageDays)
const hireCost = computed(() => hireAmount.value - hireAmount.value * document.value.costs.hireCommPercent / 100)
const portMarginFuel = computed(() => document.value.margins.portIdleDays * document.value.fuel.portIdleFuel + document.value.margins.portWorkingDays * document.value.fuel.portWorkingFuel)
const hasPortMargins = computed(() => document.value.margins.portIdleDays > 0 || document.value.margins.portWorkingDays > 0)
const resultItems = computed(() => [
  { label: t('budget.detail.metrics.totalIncome'), value: results.value.totalIncome },
  { label: t('budget.detail.metrics.netIncome'), value: results.value.netIncome },
  { label: t('budget.detail.metrics.operatingCost'), value: results.value.operatingCost },
  { label: t('budget.detail.metrics.totalExpenses'), value: results.value.totalExpense },
  { label: t('budget.detail.metrics.operatingProfit'), value: results.value.operatingProfit },
  { label: t('budget.detail.metrics.netProfit'), value: results.value.netProfit },
  { label: t('budget.detail.metrics.hireLevelPerDay'), value: results.value.hirePerDayLevel },
  { label: t('budget.detail.metrics.averageDailyProfit'), value: results.value.dailyProfit },
])
const cargoTotals = computed(() => document.value.cargos.reduce((total, cargo) => ({
  income: total.income + numberOf(cargo.income),
  addComm: total.addComm + cargoCommission(cargo, 'addCommRate'),
  brokerage: total.brokerage + cargoCommission(cargo, 'brokerageRate'),
  tax: total.tax + cargoCommission(cargo, 'frtTaxRate'),
  demurrage: total.demurrage + numberOf(cargo.demurrage),
  dispatch: total.dispatch + numberOf(cargo.dispatch),
}), { income: 0, addComm: 0, brokerage: 0, tax: 0, demurrage: 0, dispatch: 0 }))
onIonViewWillEnter(() => { void load() })
async function load() { const id = Number(route.params.id); if (!Number.isFinite(id) || id <= 0) { error.value = t('budget.detail.invalidId'); loading.value = false; return }; loading.value = true; error.value = ''; try { await store.loadDetail(id) } catch (cause) { error.value = cause instanceof Error ? cause.message : t('budget.detail.loadFailed') } finally { loading.value = false } }
function edit() { void router.push({ name: 'esti-deploy-editor', query: { id: String(route.params.id) } }) }
async function share() { await shareText(store.name || t('budget.detail.shareTitle'), t('budget.detail.shareText', { name: store.name || t('common.unnamed'), income: amount(results.value.totalIncome), expense: amount(results.value.totalExpense), profit: amount(results.value.netProfit) })) }
async function exportPdf() { if (exporting.value) return; exporting.value = true; try { await exportVoyageBudgetPdf({ name: store.name, shipName: store.shipName || store.shipId, document: document.value }); const toast = await toastController.create({ message: t('budget.detail.pdfGenerated'), color: 'success', duration: 1800, position: 'top' }); await toast.present() } catch (cause) { const toast = await toastController.create({ message: cause instanceof Error ? cause.message : t('budget.detail.pdfExportFailed'), color: 'danger', duration: 2200, position: 'top' }); await toast.present() } finally { exporting.value = false } }
async function confirmDelete() { const id = Number(route.params.id); if (!Number.isFinite(id) || id <= 0) return; const alert = await alertController.create({ header: t('budget.detail.deleteTitle'), message: t('budget.detail.deleteMessage'), buttons: [{ text: t('common.cancel'), role: 'cancel' }, { text: t('common.delete'), role: 'destructive', handler: async () => { await store.remove(id); await router.replace('/tabs/esti-deploy') } }] }); await alert.present() }
function numberOf(value: unknown) { const result = Number(value); return Number.isFinite(result) ? result : 0 }
function amount(value: unknown) { return formatAmount(numberOf(value)) }
function profitClass(value: unknown) { return numberOf(value) < 0 ? 'profit-negative' : 'profit-positive' }
function portName(id: string) { return document.value.ports.find((port) => port.id === id)?.port.portName || t('budget.detail.portNotSelected') }
function taskLabel(task: BudgetPortTask) { const keys: Record<BudgetPortTask, string> = { ballast: 'budget.detail.task.ballast', load: 'budget.detail.task.load', discharge: 'budget.detail.task.discharge', bunker: 'budget.detail.task.bunker', canal: 'budget.detail.task.canal', pass: 'budget.detail.task.pass', routing: 'budget.detail.task.routing', snug: 'budget.detail.task.snug', repair: 'budget.detail.task.repair', transit: 'budget.detail.task.transit' }; return t(keys[task]) }
function dateText(value?: string | number) { return formatDateTime(value, t('budget.detail.notRecorded')) }
function cargoCommission(cargo: BudgetCargo, field: 'addCommRate' | 'brokerageRate' | 'frtTaxRate') { return numberOf(cargo.income) * numberOf(cargo[field]) / 100 }
function isRoutingPort(port: BudgetPort) { return port.taskType === 'routing' || Boolean(port.port.isWayPoint) }
function portDisplayName(port: BudgetPort) { return String(port.port.portName || port.port.fullName || t('budget.detail.unnamedPort')) }
function fuelLeg(portId: string) { return store.fuelLegDetails.find((detail) => detail.arrivalPortId === portId) }
function mainFuelForLeg(index: number) { return document.value.ports[index - 1]?.isLaden ? document.value.fuel.ladenFuelType : document.value.fuel.ballastFuelType }
</script>

